/** 2D position (x, y). */
typealias Position2 = Float2
/** 3D position (x, y, z) in world or local space. */
typealias Position = Float3
/** Euler angle rotation in degrees (pitch, yaw, roll). */
typealias Rotation = Float3
/**
 * Non-uniform scale (x, y, z).
 *
 * **Gotcha** — prefer the positional single-arg form `Scale(1f)` over the named
 * form `Scale(x = 1f)` when you want a uniform scale:
 *
 *   - `Scale(1f)` resolves to kotlin-math's `Float3(v: Float)` constructor and
 *     fills all three components → `(1, 1, 1)`.
 *   - `Scale(x = 1f)` resolves to the three-arg primary constructor with
 *     defaults `y = 0f, z = 0f` → `(1, 0, 0)`. Filament treats that as a
 *     singular transform: quaternion decomposition returns NaN, any child
 *     volume collapses, and frame-loop drivers (physics, animation) feed the
 *     NaN back through their integrators, silently breaking the whole scene
 *     subtree.
 *
 * Lesson from the `PhysicsDemo` spheres-invisible bug.
 */
typealias Scale = Float3
/** Unit direction vector (x, y, z). */
typealias Direction = Float3
/** 3D size / extents (width, height, depth). */
typealias Size = Float3
/** 4x4 transformation matrix (position + rotation + scale). */
typealias Transform = Mat4
/** RGBA color (r, g, b, a) with values typically in [0..1]. */
typealias Color = Float4

/**
 * Construct a [Transform] matrix from position, quaternion rotation, and scale.
 */
fun Transform(
    position: Position = Position(),
    quaternion: Quaternion = Quaternion(),
    scale: Scale = Scale(1.0f)
) = translation(position) * rotation(quaternion) * scale(scale)

/**
 * Construct a [Transform] matrix from position, Euler angle rotation (degrees), and scale.
 */
fun Transform(
    position: Position = Position(),
    rotation: Rotation,
    scale: Scale = Scale(1.0F)
) = translation(position) * rotation(rotation.toQuaternion()) * scale(scale)

fun FloatArray.toFloat3() = this.let { (x, y, z) -> Float3(x, y, z) }
fun FloatArray.toFloat4() = this.let { (x, y, z, w) -> Float4(x, y, z, w) }
fun DoubleArray.toFloat4() = this.map { it.toFloat() }.let { (x, y, z, w) -> Float4(x, y, z, w) }
fun FloatArray.toPosition() = this.let { (x, y, z) -> Position(x, y, z) }
fun FloatArray.toRotation() = this.let { (x, y, z) -> Rotation(x, y, z) }
fun FloatArray.toScale() = this.let { (x, y, z) -> Scale(x, y, z) }
fun FloatArray.toDirection() = this.let { (x, y, z) -> Direction(x, y, z) }

fun Rotation.toQuaternion(order: RotationsOrder = RotationsOrder.ZYX) =
    Quaternion.fromEuler(this, order)

fun Quaternion.toRotation(order: RotationsOrder = RotationsOrder.ZYX) = eulerAngles(this, order)

fun FloatArray.toSize() = this.let { (x, y, z) -> Size(x, y, z) }

//TODO: Remove when everything use Float3
fun Float3.toVector3() = Vector3(x, y, z)

//TODO: Remove when everything use Float3
fun Vector3.toFloat3() = Float3(x, y, z)


fun Mat3.toColumnsFloatArray() = floatArrayOf(
    x.x, x.y, x.z,
    y.x, y.y, y.z,
    z.x, z.y, z.z
)

/**
 * Writes this [Mat3]'s 9 columns into [out] starting at [offset] (column-major).
 *
 * Allocation-free counterpart to [toColumnsFloatArray]. Pass a reusable scratch
 * buffer to avoid the per-call `FloatArray(9)` allocation on hot paths.
 *
 * @return [out], for chaining.
 */
fun Mat3.copyColumnsInto(out: FloatArray, offset: Int = 0): FloatArray {
    require(out.size >= offset + 9) {
        "FloatArray needs >= 9 slots from offset $offset (size=${out.size})"
    }
    out[offset] = x.x; out[offset + 1] = x.y; out[offset + 2] = x.z
    out[offset + 3] = y.x; out[offset + 4] = y.y; out[offset + 5] = y.z
    out[offset + 6] = z.x; out[offset + 7] = z.y; out[offset + 8] = z.z
    return out
}

/**
 * Returns this [Mat4]'s 16 components as a column-major [DoubleArray].
 *
 * Fills the result directly rather than going through [toColumnsFloatArray] and a boxed
 * `List<Double>` — one allocation instead of three for the same conversion.
 */
fun Mat4.toColumnsDoubleArray() = doubleArrayOf(
    x.x.toDouble(), x.y.toDouble(), x.z.toDouble(), x.w.toDouble(),
    y.x.toDouble(), y.y.toDouble(), y.z.toDouble(), y.w.toDouble(),
    z.x.toDouble(), z.y.toDouble(), z.z.toDouble(), z.w.toDouble(),
    w.x.toDouble(), w.y.toDouble(), w.z.toDouble(), w.w.toDouble()
)

/**
 * Extracts the rotation component of this transform as a [Quaternion].
 *
 * **Use this, never `Mat4.toQuaternion()`, on any matrix that may carry a scale.** The
 * kotlin-math member `toQuaternion()` (and the same-named `dev.romainguy.kotlin.math.quaternion`
 * extension) runs Shepperd's trace method straight on the raw basis, which is only valid for an
 * orthonormal one. A `T·R·S` matrix folds `S` into the trace, so the extracted quaternion is
 * renormalised into a *different* rotation — uniform scale included, which is the surprising
 * part. Measured against `R = rotX(-90°)`, `|scale| = 2`: the trace method returns a rotation
 * 16.26° off; on a tilted axis at scale 10 it is 32.38° off, and at scale `(0.25, 2, 10)`,
 * 78.11° off. This accessor divides each basis column by its length first, which is exact
 * (measured error 0.00° through float32 rounding) wherever the basis is still orthogonal:
 * every single-level `T·R·S`, uniform or not, and every chain whose scales are all uniform.
 * See #3738.
 *
 * A pure yaw at exactly 0° or 180° happens to survive the trace method unscathed, and *any*
 * pure yaw keeps the axis exactly (only the angle is corrupted) — which is why scale bugs here
 * hide from axis-only or turntable-only test scenes.
 *
 * Three families of matrix are not a plain rotation, and this accessor returns a best-effort
 * answer rather than failing:
 *
 *  - **Shear** — a non-uniformly scaled *ancestor* with a rotation below it leaves a
 *    non-orthogonal world basis. On that path only, Higham's polar-decomposition iteration
 *    extracts the closest orthonormal frame. This recovers the exact composed rotation (within
 *    float rounding) for one non-uniformly scaled ancestor. With nested non-uniform scales the
 *    polar factor is still the closest orthonormal frame, but is not necessarily the rotation
 *    obtained by composing the nodes' quaternions. Orthogonal bases retain the cheaper,
 *    bit-for-bit column-normalised path.
 *  - **Mirror** — an *odd* number of negative scale axes makes the basis left-handed, which is
 *    not a rotation at all: the result is finite and unit but arbitrary. An *even* number is a
 *    genuine rotation — `(-1, -1, 1)` is a 180° turn about Z — and is extracted exactly. Nothing
 *    downstream can tell the two apart: [Mat4.scale] reports column *lengths*, so it returns
 *    `(2, 2, 2)` for a scale of `(-2, -2, -2)`.
 *  - **Collapse** — a zero scale on an axis makes that column zero-length, so normalising it is
 *    `0 / 0 = NaN`, and unguarded that NaN would propagate into every child transform and into
 *    any frame-loop driver integrating this value (see the [Scale] doc). The NaN belongs to this
 *    accessor, not to the defect it fixes: the trace method stays finite on a collapsed basis and
 *    returns a silently wrong rotation instead (12.73° off with one axis gone, up to 180° with
 *    three). When exactly one axis has collapsed the rotation is still fully determined by the
 *    other two, and is recovered exactly from their cross product; with two or three axes gone
 *    nothing is left to recover and the identity is returned. Either way the result is finite.
 */
val Mat4.quaternion: Quaternion
    get() {
        val normalizedBasis = rotation(this)
        val quaternion = normalizedBasis.toQuaternion()
        // `rotation()` divides each column by its length, so a collapsed axis yields NaN.
        // Only then pay for the reconstruction below.
        if (quaternion.hasNaNComponent) return collapsedBasisQuaternion()

        val right = normalizedBasis.x.xyz
        val up = normalizedBasis.y.xyz
        val forward = normalizedBasis.z.xyz
        val isOrthogonal = abs(dot(right, up)) <= ORTHOGONAL_BASIS_EPSILON &&
            abs(dot(right, forward)) <= ORTHOGONAL_BASIS_EPSILON &&
            abs(dot(up, forward)) <= ORTHOGONAL_BASIS_EPSILON
        // Preserve the established result exactly for the overwhelmingly common unsheared path.
        if (isOrthogonal) return quaternion

        return polarQuaternionOrNull() ?: quaternion
    }

private const val ORTHOGONAL_BASIS_EPSILON = 1e-4f
private const val POLAR_CONVERGENCE_EPSILON = 1e-6f
private const val POLAR_MAX_ITERATIONS = 20

/**
 * Returns the orthogonal factor of this 3×3 basis, or `null` when it cannot be computed safely.
 *
 * The original sheared basis is required here: independently normalising its columns changes its
 * polar factor and does not recover `Rp·Rc` from `Rp·S·Rc`. A uniform scalar, on the other hand,
 * leaves the polar factor unchanged, so the basis is first divided by `cbrt(det)` — the guards
 * below then hold for a millimetre-scale model as well as for a kilometre-scale one.
 *
 * Higham's Newton iteration `X ← ½(γX + X^-T/γ)` with the Frobenius scaling
 * `γ = sqrt(‖X^-1‖ / ‖X‖)` converges in a handful of steps whatever the ratio between the scale
 * axes. A left-handed basis (`det ≤ 0`) is a mirror rather than a rotation: `null` keeps
 * [quaternion]'s established finite best-effort result for it.
 */
// The 3×3 algebra is unrolled into locals so the hot path allocates nothing, which makes the body
// long; each early `null` is a distinct numerical guard (non-finite or non-positive determinant).
@Suppress("LongMethod", "ReturnCount")
private fun Mat4.polarQuaternionOrNull(): Quaternion? {
    // Column-major: element(row, column) lives at the corresponding component of x/y/z.
    var a00 = x.x
    var a01 = y.x
    var a02 = z.x
    var a10 = x.y
    var a11 = y.y
    var a12 = z.y
    var a20 = x.z
    var a21 = y.z
    var a22 = z.z

    val initialDeterminant =
        a00 * (a11 * a22 - a12 * a21) -
            a01 * (a10 * a22 - a12 * a20) +
            a02 * (a10 * a21 - a11 * a20)
    if (!initialDeterminant.isFinite() || initialDeterminant <= 0f) return null
    val unitVolume = (1.0 / cbrt(initialDeterminant.toDouble())).toFloat()
    if (!unitVolume.isFinite()) return null
    a00 *= unitVolume; a01 *= unitVolume; a02 *= unitVolume
    a10 *= unitVolume; a11 *= unitVolume; a12 *= unitVolume
    a20 *= unitVolume; a21 *= unitVolume; a22 *= unitVolume

    var iterations = 0
    while (iterations++ < POLAR_MAX_ITERATIONS) {
        val determinant =
            a00 * (a11 * a22 - a12 * a21) -
                a01 * (a10 * a22 - a12 * a20) +
                a02 * (a10 * a21 - a11 * a20)
        if (!determinant.isFinite() || determinant <= 0f) return null

        // Cofactor(A) / det(A) is A^-T, exactly the matrix Higham's iteration needs.
        val inverseTranspose00 = (a11 * a22 - a12 * a21) / determinant
        val inverseTranspose01 = (a12 * a20 - a10 * a22) / determinant
        val inverseTranspose02 = (a10 * a21 - a11 * a20) / determinant
        val inverseTranspose10 = (a02 * a21 - a01 * a22) / determinant
        val inverseTranspose11 = (a00 * a22 - a02 * a20) / determinant
        val inverseTranspose12 = (a01 * a20 - a00 * a21) / determinant
        val inverseTranspose20 = (a01 * a12 - a02 * a11) / determinant
        val inverseTranspose21 = (a02 * a10 - a00 * a12) / determinant
        val inverseTranspose22 = (a00 * a11 - a01 * a10) / determinant

        val norm = sqrt(
            a00 * a00 + a01 * a01 + a02 * a02 +
                a10 * a10 + a11 * a11 + a12 * a12 +
                a20 * a20 + a21 * a21 + a22 * a22
        )
        val inverseNorm = sqrt(
            inverseTranspose00 * inverseTranspose00 + inverseTranspose01 * inverseTranspose01 +
                inverseTranspose02 * inverseTranspose02 + inverseTranspose10 * inverseTranspose10 +
                inverseTranspose11 * inverseTranspose11 + inverseTranspose12 * inverseTranspose12 +
                inverseTranspose20 * inverseTranspose20 + inverseTranspose21 * inverseTranspose21 +
                inverseTranspose22 * inverseTranspose22
        )
        val gamma = sqrt(inverseNorm / norm)
        if (!gamma.isFinite() || gamma <= 0f) return null
        val half = 0.5f * gamma
        val halfInverse = 0.5f / gamma

        val n00 = half * a00 + halfInverse * inverseTranspose00
        val n01 = half * a01 + halfInverse * inverseTranspose01
        val n02 = half * a02 + halfInverse * inverseTranspose02
        val n10 = half * a10 + halfInverse * inverseTranspose10
        val n11 = half * a11 + halfInverse * inverseTranspose11
        val n12 = half * a12 + halfInverse * inverseTranspose12
        val n20 = half * a20 + halfInverse * inverseTranspose20
        val n21 = half * a21 + halfInverse * inverseTranspose21
        val n22 = half * a22 + halfInverse * inverseTranspose22
        val maxChange = maxOf(
            maxOf(abs(n00 - a00), abs(n01 - a01), abs(n02 - a02)),
            maxOf(abs(n10 - a10), abs(n11 - a11), abs(n12 - a12)),
            maxOf(abs(n20 - a20), abs(n21 - a21), abs(n22 - a22))
        )
        if (!maxChange.isFinite()) return null

        a00 = n00
        a01 = n01
        a02 = n02
        a10 = n10
        a11 = n11
        a12 = n12
        a20 = n20
        a21 = n21
        a22 = n22
        // Newton converges quadratically: a step below 1e-6 leaves an error far under float
        // rounding, and an absolute bar at float epsilon could oscillate by one ulp forever.
        if (maxChange < POLAR_CONVERGENCE_EPSILON) break
    }

    return Transform(
        right = Float3(a00, a10, a20),
        up = Float3(a01, a11, a21),
        forward = Float3(a02, a12, a22)
    ).toQuaternion().takeUnless { it.hasNaNComponent }
}

/**
 * True when any component is NaN — what [rotation] hands back for a basis with a zero-length
 * column, since normalising it is `0 / 0`.
 *
 * Answered by one sum rather than four `isNaN()` tests: NaN propagates through addition, so the
 * two agree on every value a normalised basis can produce, and the check reads as the single
 * question it is.
 */
private val Quaternion.hasNaNComponent: Boolean
    get() = (x + y + z + w).isNaN()

/**
 * Best-effort rotation for a basis with at least one zero-length column, keeping [quaternion]
 * finite instead of NaN. Rebuilds a single collapsed axis from the cross product of the two
 * survivors (exact, since a right-handed frame is determined by any two of its axes); gives up
 * on the identity when two or more axes are gone, or when the survivors are parallel and their
 * cross product is itself zero.
 */
private fun Mat4.collapsedBasisQuaternion(): Quaternion {
    val right = x.xyz
    val up = y.xyz
    val forward = z.xyz
    val rightAlive = dot(right, right) > 0f
    val upAlive = dot(up, up) > 0f
    val forwardAlive = dot(forward, forward) > 0f
    val basis = when {
        !rightAlive && upAlive && forwardAlive ->
            Transform(right = cross(up, forward), up = up, forward = forward)
        rightAlive && !upAlive && forwardAlive ->
            Transform(right = right, up = cross(forward, right), forward = forward)
        rightAlive && upAlive && !forwardAlive ->
            Transform(right = right, up = up, forward = cross(right, up))
        // Two or three axes gone: nothing is left to recover the orientation from.
        else -> return Quaternion()
    }
    val rebuilt = rotation(basis).toQuaternion()
    // The rebuilt axis is itself zero when the two survivors are parallel (a fully sheared,
    // collapsed basis), which would hand back a NaN again.
    return if (rebuilt.hasNaNComponent) Quaternion() else rebuilt
}

/** Transforms a 3D point by this matrix (applies translation, rotation, and scale). */
operator fun Mat4.times(v: Float3) = (this * Float4(v, 1f)).xyz

fun Mat4.toMatrix() = Matrix(toColumnsFloatArray())

fun Mat4.toColumnsFloatArray() = floatArrayOf(
    x.x, x.y, x.z, x.w,
    y.x, y.y, y.z, y.w,
    z.x, z.y, z.z, z.w,
    w.x, w.y, w.z, w.w
)

/**
 * Writes this [Mat4]'s 16 columns into [out] starting at [offset] (column-major).
 *
 * Allocation-free counterpart to [toColumnsFloatArray]. Pass a reusable scratch
 * buffer to avoid the per-call `FloatArray(16)` allocation on hot paths such as
 * `TransformManager.setTransform`, fired thousands of times per second on an
 * animated scene.
 *
 * @return [out], for chaining.
 */
fun Mat4.copyColumnsInto(out: FloatArray, offset: Int = 0): FloatArray {
    require(out.size >= offset + 16) {
        "FloatArray needs >= 16 slots from offset $offset (size=${out.size})"
    }
    out[offset] = x.x; out[offset + 1] = x.y; out[offset + 2] = x.z; out[offset + 3] = x.w
    out[offset + 4] = y.x; out[offset + 5] = y.y; out[offset + 6] = y.z; out[offset + 7] = y.w
    out[offset + 8] = z.x; out[offset + 9] = z.y; out[offset + 10] = z.z; out[offset + 11] = z.w
    out[offset + 12] = w.x; out[offset + 13] = w.y; out[offset + 14] = w.z; out[offset + 15] = w.w
    return out
}

fun FloatArray.toTransform() = Transform(
    x = Float4(this[0], this[1], this[2], this[3]),
    y = Float4(this[4], this[5], this[6], this[7]),
    z = Float4(this[8], this[9], this[10], this[11]),
    w = Float4(this[12], this[13], this[14], this[15])
)

fun DoubleArray.toTransform() = this.map { it.toFloat() }.toFloatArray().toTransform()

fun lerp(start: Float3, end: Float3, deltaSeconds: Float) = mix(start, end, deltaSeconds)

/**
 * Computes a quaternion that orients a surface given its [normal] direction.
 *
 * Derives a right-handed tangent/bitangent/normal frame and returns the
 * corresponding rotation quaternion. Used for orienting planar geometry
 * (planes, decals) to face a given direction.
 */
fun normalToTangent(normal: Float3): Quaternion {
    var tangent: Float3
    val bitangent: Float3

    // Calculate basis vectors (+x = tangent, +y = bitangent, +z = normal).
    tangent = cross(Direction(y = 1.0f), normal)

    // Uses almostEqualRelativeAndAbs for equality checks that account for float inaccuracy.
    if (dot(tangent, tangent) == 0.0f) {
        bitangent = normalize(cross(normal, Direction(x = 1.0f)))
        tangent = normalize(cross(bitangent, normal))
    } else {
        tangent = normalize(tangent)
        bitangent = normalize(cross(normal, tangent))
    }
    // Rotation of a 4x4 Transformation Matrix is represented by the top-left 3x3 elements.
    // `tangent` and `bitangent` are unit by construction but `normal` is the caller's vector,
    // so the forward column can be any length: extract through `quaternion`, which normalises
    // the columns first. With a length-5 normal the raw trace method lands 18.92° off (#3738).
    return Transform(right = tangent, up = bitangent, forward = normal).quaternion
}

/**
 * Spherical / linear interpolate a transform toward [end] with frame-rate-independent
 * exponential decay.
 *
 * The interpolation factor is `1 - exp(-speed * deltaSeconds)`, which makes the result
 * invariant to the time-step distribution: 30 ticks at 1/30 s and 120 ticks at 1/120 s
 * produce the same trajectory over the same wall-clock total.
 *
 * Pre-#1126 this function used the linear approximation `clamp(speed * dt, 0, 1)` —
 * correct only at high frame rates, with visible divergence (and outright snap-to-target
 * when `speed * dt > 1`) at lower frame rates.
 *
 * @param start Current transform.
 * @param end Target transform.
 * @param deltaSeconds Time since last call. Negative values are clamped to 0.
 * @param speed Convergence rate (s⁻¹). Higher = faster approach. The 63 % point is
 * reached after `1 / speed` seconds regardless of the caller's tick rate.
 */
fun slerp(
    start: Transform,
    end: Transform,
    deltaSeconds: Double,
    speed: Float
): Transform {
    val (position, quaternion, scale) = slerp(
        startPosition = start.position,
        startQuaternion = start.quaternion,
        startScale = start.scale,
        endPosition = end.position,
        endQuaternion = end.quaternion,
        endScale = end.scale,
        deltaSeconds = deltaSeconds,
        speed = speed
    )
    return Transform(position, quaternion, scale)
}

/**
 * Pre-decomposed TRS-tuple variant of [slerp] — interpolates position/rotation/scale
 * components directly without ever building or decomposing a [Transform] (`Mat4`).
 *
 * The `slerp(start: Transform, end: Transform, …)` overload reads `.position`,
 * `.quaternion` and `.scale` off each [Transform], and **every one of those accessors runs
 * a matrix decomposition** (a W-column extract, a polar decomposition, and three column-length
 * `sqrt`s) — six decompositions per call. Callers that already hold the components (e.g. a
 * [io.github.sceneview.node.Node] whose `position` / `quaternion` / `scale` are cached since
 * #2187) should call this overload to skip all of them, then rebuild a `Transform` once from
 * the result if they need the matrix form.
 *
 * Uses the exact same frame-rate-independent factor `1 - exp(-speed * deltaSeconds)` as the
 * [Transform] overload, so trajectories are identical.
 *
 * @param startPosition Current position.
 * @param startQuaternion Current rotation.
 * @param startScale Current scale.
 * @param endPosition Target position.
 * @param endQuaternion Target rotation.
 * @param endScale Target scale.
 * @param deltaSeconds Time since last call. Negative values are clamped to 0.
 * @param speed Convergence rate (s⁻¹). The 63 % point is reached after `1 / speed` seconds
 * regardless of the caller's tick rate.
 * @return A [Triple] of the interpolated `(position, quaternion, scale)`.
 */
fun slerp(
    startPosition: Position,
    startQuaternion: Quaternion,
    startScale: Scale,
    endPosition: Position,
    endQuaternion: Quaternion,
    endScale: Scale,
    deltaSeconds: Double,
    speed: Float
): Triple<Position, Quaternion, Scale> {
    val lerpFactor = if (deltaSeconds <= 0.0 || speed <= 0f) {
        0f
    } else {
        (1.0 - exp(-speed.toDouble() * deltaSeconds)).toFloat().coerceIn(0f, 1f)
    }
    return Triple(
        lerp(startPosition, endPosition, lerpFactor),
        slerp(startQuaternion, endQuaternion, lerpFactor),
        lerp(startScale, endScale, lerpFactor)
    )
}

/**
 * If rendering in linear space, first convert the values to linear space by rising to the power 2.2
 *
 * Builds the result array in place rather than through a boxed `List<Float>` intermediate — one
 * allocation instead of two.
 */
fun FloatArray.toLinearSpace() = FloatArray(size) { pow(this[it], 2.2f) }

/**
 * Creates a view matrix looking from [eye] toward [target] with Y-up.
 */
fun lookAt(eye: Position, target: Position): Mat4 {
    return lookAt(eye, target - eye, Direction(y = 1.0f))
}

/**
 * Returns a quaternion that orients an object at [eye] to look along [direction] with Y-up.
 */
fun lookTowards(eye: Position, direction: Direction) =
    lookTowards(eye, direction, Direction(y = 1.0f)).toQuaternion()

fun List<Position2>.getCenter() = reduce { total, position -> total + position } / size.toFloat()
fun List<Position>.getCenter() = reduce { total, position -> total + position } / size.toFloat()

fun colorOf(r: Float = 0.0f, g: Float = 0.0f, b: Float = 0.0f, a: Float = 1.0f) = Color(r, g, b, a)
fun colorOf(rgb: Float = 0.0f, a: Float = 1.0f) = colorOf(r = rgb, g = rgb, b = rgb, a = a)

fun FloatArray.toColor() = Color(this[0], this[1], this[2], this.getOrNull(3) ?: 1.0f)

fun dev.romainguy.kotlin.math.Ray.toCollisionRay() =
    io.github.sceneview.collision.Ray(origin.toVector3(), direction.toVector3())

// Float comparison utilities
fun Float.equals(other: Float, delta: Float): Boolean = abs(this - other) <= delta

fun Float.compareTo(v: Float, delta: Float): Float = when {
    equals(v, delta) -> 0.0f
    else -> compareTo(v).toFloat()
}

/**
 * Returns true if two floats are equal within a tolerance. Useful for comparing floating point
 * numbers while accounting for the limitations in floating point precision.
 */
infix fun Float.almostEquals(other: Float): Boolean {
    val epsilon = max(ulp(this), ulp(other)) * 2
    return abs(this - other) <= epsilon
}

